"""Bandes 1024x14 fournies pour le thème de logs SentriX.

Les PNG sont stockés en base64 afin que le déploiement reste 100 % Python et ne dépende
pas de fichiers binaires absents du dépôt. Les noms générés restent banner_error.png,
banner_success.png, banner_warning.png, banner_info.png et banner_special.png.
"""
from __future__ import annotations

import base64

from utils import log_banners

_BANNERS_B64 = {
    "error": "",
    "success": "",
    "warning": "",
    "info": "",
    "special": "",
}


def exact_banner_png(style: str) -> bytes:
    safe_style = style if style in _BANNERS_B64 else "info"
    return base64.b64decode(_BANNERS_B64[safe_style])


def install() -> None:
    """Remplace le générateur de secours par les cinq bandes exactes fournies."""
    cached = getattr(log_banners._banner_png, "cache_clear", None)
    if callable(cached):
        cached()
    log_banners._banner_png = exact_banner_png
    log_banners.BANNER_WIDTH = 1024
    log_banners.BANNER_HEIGHT = 14
